(() => {
  'use strict';
  const root=document.createElement('main');root.id='renderWorkspace';root.className='render-workspace';root.hidden=true;
  root.innerHTML=`<aside class="render-gallery"><h2>Renders del proyecto</h2><p class="render-meta" id="renderTotal">Sin imágenes cargadas</p><button class="tool-button" id="renderRestore">Cargar renders de ejemplo (CTC)</button><div class="render-thumbs" id="renderThumbs" aria-label="Elegir imagen"></div></aside><section class="render-card" id="renderCard"><header class="render-head"><div><p class="eyebrow">GALERÍA / IMÁGENES 2D</p><h1 id="renderTitle">Render 1</h1><p class="render-meta" id="renderInfo"></p></div><div class="cad-actions"><button class="tool-button primary" id="renderOpen">Cargar imágenes</button><input id="renderFiles" hidden type="file" multiple accept="image/jpeg,image/png,image/webp,.jpg,.jpeg,.png,.webp"><a class="tool-button render-download" id="renderDownload" download>Descargar imagen</a></div></header><div class="render-toolbar"><button class="tool-button" id="renderPrevious" aria-label="Render anterior">← Anterior</button><span id="renderCounter" class="render-counter"></span><button class="tool-button" id="renderNext" aria-label="Render siguiente">Siguiente →</button><button class="tool-button" id="renderFit">Ajustar</button><button class="tool-button" id="renderActual">100 %</button><button class="tool-button" id="renderMinus" aria-label="Alejar">−</button><output id="renderZoom">100 %</output><button class="tool-button" id="renderPlus" aria-label="Acercar">+</button><button class="tool-button" id="renderFullscreen">Pantalla completa</button></div><div class="render-stage" id="renderStage" tabindex="0" aria-label="Render. Rueda para ampliar, arrastrar para mover, flechas para cambiar de imagen y 0 para ajustar."><img class="render-image" id="renderImage" alt="" draggable="false" hidden><div class="render-stage-message" id="renderMessage" role="status">Cargando imagen…</div></div><footer class="render-foot"><span>Rueda: zoom · Arrastrar: mover · ← →: navegar</span><span>Imagen 2D · sin escala métrica ni geometría 3D</span></footer><p class="render-notice" id="renderNotice" role="status"></p></section>`;
  document.querySelector('.shell').append(root);
  const $=id=>document.getElementById(id),stage=$('renderStage'),display=$('renderImage');
  const numbers=[...Array.from({length:24},(_,i)=>i+1),...Array.from({length:22},(_,i)=>i+51),84,85,86,87,88];
  const included=numbers.map(n=>({name:n+'.jpg',src:'assets/renders/'+n+'.jpg',local:false}));
  $('renderRestore').textContent='Cargar ejemplo CTC ('+included.length+' imágenes)';
  let items=[],index=0,scale=1,x=0,y=0,width=0,height=0,drag=null,ready=false,revision=0;
  function updateTransform(){display.style.transform=`translate(${x}px,${y}px) scale(${scale})`;$('renderZoom').textContent=Math.round(scale*100)+' %';}
  function fit(){if(!ready||!stage.clientWidth||!stage.clientHeight)return;scale=Math.min((stage.clientWidth-24)/width,(stage.clientHeight-24)/height,1);x=(stage.clientWidth-width*scale)/2;y=(stage.clientHeight-height*scale)/2;updateTransform();}
  function zoom(factor,cx=stage.clientWidth/2,cy=stage.clientHeight/2){if(!ready)return;const next=Math.min(12,Math.max(.01,scale*factor));x=cx-(cx-x)*next/scale;y=cy-(cy-y)*next/scale;scale=next;updateTransform();}
  function select(next){if(!items.length){revision++;ready=false;display.hidden=true;display.removeAttribute('src');$('renderTitle').textContent='Sin renders';$('renderInfo').textContent='Carga imágenes de este proyecto o el ejemplo opcional.';$('renderCounter').textContent='0 / 0';$('renderPrevious').disabled=$('renderNext').disabled=true;$('renderDownload').hidden=true;$('renderMessage').hidden=false;$('renderMessage').textContent='Carga JPG, PNG o WebP para comenzar.';window.dispatchEvent(new Event('render-selected'));return;}index=Math.max(0,Math.min(items.length-1,next));const item=items[index],ticket=++revision;ready=false;drag=null;display.hidden=true;$('renderMessage').hidden=false;$('renderMessage').textContent='Cargando '+item.name+'…';$('renderTitle').textContent=item.name;$('renderInfo').textContent=item.local?'Imagen local · disponible durante esta sesión':'Render proporcionado · incluido en el proyecto';$('renderCounter').textContent=(index+1)+' / '+items.length;$('renderPrevious').disabled=index===0;$('renderNext').disabled=index===items.length-1;$('renderDownload').hidden=true;
    [...$('renderThumbs').children].forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));
    const loader=new Image();loader.onload=()=>{if(ticket!==revision)return;if(!loader.naturalWidth||loader.naturalWidth*loader.naturalHeight>80000000){$('renderMessage').textContent='La imagen supera el límite de 80 megapíxeles.';return;}width=loader.naturalWidth;height=loader.naturalHeight;display.src=item.src;display.alt='Render arquitectónico '+item.name;display.style.width=width+'px';display.style.height=height+'px';display.hidden=false;ready=true;$('renderMessage').hidden=true;$('renderInfo').textContent=width+' × '+height+' px · '+(item.local?'imagen local':'render incluido');$('renderDownload').href=item.src;$('renderDownload').download=item.name;$('renderDownload').hidden=false;fit();};loader.onerror=()=>{if(ticket===revision)$('renderMessage').textContent='No se pudo abrir '+item.name+'. Comprueba que sea una imagen JPG, PNG o WebP válida.';};loader.src=item.src;window.dispatchEvent(new Event('render-selected'));
  }
  function gallery(){const frag=document.createDocumentFragment();items.forEach((item,i)=>{const button=document.createElement('button');button.className='render-thumb';button.type='button';button.setAttribute('aria-label','Ver '+item.name);button.setAttribute('aria-pressed','false');const image=document.createElement('img');image.src=item.src;image.alt='';image.loading='lazy';const label=document.createElement('span');label.textContent=item.name;button.append(image,label);button.onclick=()=>select(i);frag.append(button);});$('renderThumbs').replaceChildren(frag);$('renderTotal').textContent=items.length+' imágenes · '+(items===included?'incluidas':'selección local');select(0);}
  function release(){for(const item of items)if(item.local)URL.revokeObjectURL(item.src);}
  function open(files,preserveOrder=false){const sorted=preserveOrder?[...files]:[...files].sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true})),accepted=[],rejected=[];let bytes=0;for(const file of sorted){if(!/\.(jpe?g|png|webp)$/i.test(file.name)){rejected.push(file.name+': formato no compatible.');continue;}if(file.size>32*1024*1024){rejected.push(file.name+': supera 32 MB.');continue;}if(accepted.length>=100||bytes+file.size>512*1024*1024){rejected.push(file.name+': supera el límite de 100 imágenes o 512 MB por selección.');continue;}bytes+=file.size;accepted.push(file);}
    $('renderNotice').textContent=rejected.slice(0,8).join('\n')+(rejected.length>8?'\nY '+(rejected.length-8)+' archivos más omitidos.':'');if(!accepted.length)return;
    revision++;display.removeAttribute('src');release();items=accepted.map(file=>({name:file.name,src:URL.createObjectURL(file),local:true}));gallery();
  }
  $('renderOpen').onclick=()=>$('renderFiles').click();$('renderFiles').onchange=e=>{open(e.target.files);e.target.value='';};$('renderRestore').onclick=()=>{revision++;display.removeAttribute('src');release();items=included;$('renderNotice').textContent='';gallery();};
  $('renderPrevious').onclick=()=>select(index-1);$('renderNext').onclick=()=>select(index+1);$('renderFit').onclick=fit;$('renderActual').onclick=()=>{if(!ready)return;scale=1;x=(stage.clientWidth-width)/2;y=(stage.clientHeight-height)/2;updateTransform();};$('renderPlus').onclick=()=>zoom(1.25);$('renderMinus').onclick=()=>zoom(.8);
  stage.addEventListener('wheel',e=>{e.preventDefault();const r=stage.getBoundingClientRect();zoom(Math.exp(-e.deltaY*.001),e.clientX-r.left,e.clientY-r.top);},{passive:false});
  stage.onpointerdown=e=>{if(e.button!==0||!ready)return;stage.focus();stage.setPointerCapture(e.pointerId);drag={px:e.clientX,py:e.clientY,x,y};};stage.onpointermove=e=>{if(!drag)return;x=drag.x+e.clientX-drag.px;y=drag.y+e.clientY-drag.py;updateTransform();};stage.onpointerup=stage.onpointercancel=()=>{drag=null;};stage.ondblclick=fit;
  stage.onkeydown=e=>{if(['ArrowLeft','ArrowRight','0','+','=','-'].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft')select(index-1);if(e.key==='ArrowRight')select(index+1);if(e.key==='0')fit();if(e.key==='+'||e.key==='=')zoom(1.25);if(e.key==='-')zoom(.8);};
  root.ondragover=e=>{e.preventDefault();root.classList.add('drop-active');};root.ondragleave=()=>root.classList.remove('drop-active');root.ondrop=e=>{e.preventDefault();root.classList.remove('drop-active');open(e.dataTransfer.files);};
  $('renderFullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('renderCard').requestFullscreen();}catch{$('renderNotice').textContent='Pantalla completa no disponible en este navegador.';}};
  new ResizeObserver(fit).observe(stage);
  const cad=$('cadTab').onclick,pdf=$('pdfTab').onclick;
  $('cadTab').onclick=()=>{root.hidden=true;$('rendersTab').setAttribute('aria-pressed','false');cad();};$('pdfTab').onclick=()=>{root.hidden=true;$('rendersTab').setAttribute('aria-pressed','false');pdf();};
  $('rendersTab').onclick=()=>{root.hidden=false;$('cadWorkspace').hidden=true;document.querySelector('.workspace').hidden=true;document.querySelector('.rail').hidden=true;$('rendersTab').setAttribute('aria-pressed','true');$('cadTab').setAttribute('aria-pressed','false');$('pdfTab').setAttribute('aria-pressed','false');fit();};
  window.archRenders={snapshot:()=>items.map(item=>({...item})),restore:files=>{if(files.length)open(files,true);else{release();items=[];gallery();}},clear:()=>{release();items=[];gallery();},current:()=>items[index],link:floorId=>{if(items[index])items[index].floorId=floorId||null;},restoreLinks:links=>{items.forEach((item,i)=>item.floorId=links[i]?.floorId||null);window.dispatchEvent(new Event('render-selected'));}};
  window.addEventListener('beforeunload',release);gallery();$('cadTab').onclick();
})();
